pub fn score_node(job_cpu: u32, job_ram: u32, node_residual_cpu: u32, node_residual_ram: u32, node_capacity_cpu: u32, node_capacity_ram: u32, step_index: usize, total_jobs: usize, active_nodes_count: usize, mean_cpu_residual: f64, mean_ram_residual: f64, next_job_cpu: u32, next_job_ram: u32) -> f64 {
    let cpu_norm = node_residual_cpu as f64 / node_capacity_cpu as f64;
    let ram_norm = node_residual_ram as f64 / node_capacity_ram as f64;

    let imbalance_penalty = (cpu_norm - ram_norm).abs();

    // Dynamic horizon awareness
    let step_fraction = step_index as f64 / total_jobs as f64;
    let lookahead_factor = if step_fraction < 0.5 { 1.0 } else { 2.0 };

    // Lookahead awareness (k=2)
    let next_cpu_norm = (node_residual_cpu + next_job_cpu) as f64 / node_capacity_cpu as f64;
    let next_ram_norm = (node_residual_ram + next_job_ram) as f64 / node_capacity_ram as f64;

    let lookahead_imbalance_penalty = (next_cpu_norm - next_ram_norm).abs();

    // Non-linear conditionals and packing bonuses
    let cpu_packing_bonus = if next_cpu_norm < 0.5 { 1.0 } else { 0.5 };
    let ram_packing_bonus = if next_ram_norm < 0.5 { 1.0 } else { 0.5 };

    // Compaction and dead space ratio
    let cpu_compaction_score = node_residual_cpu as f64 / mean_cpu_residual;
    let ram_compaction_score = node_residual_ram as f64 / mean_ram_residual;
    let compaction_ratio_penalty = (1.0 - (cpu_compaction_score + ram_compaction_score) / 2.0).abs();

    // Combine all factors
    let score = cpu_norm + ram_norm + imbalance_penalty * 2.0 + step_fraction * 1.0 + lookahead_factor * lookahead_imbalance_penalty + cpu_packing_bonus * 0.5 + ram_packing_bonus * 0.5 + compaction_ratio_penalty;

    score
}

